package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.ElementList.ElementListIterator.ElementListIterator.ElementListIterator.ElementListIterator.ElementNode;
import org.jsoup.nodes.ElementList.ElementListIterator.ElementListIterator;
import org.jsoup.nodes.ElementList.ElementListIterator;
import org.jsoup.nodes.ElementList;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_siblingElements_TriageGen0Test {

    @Test
    public void testSiblingElements_NullParent() {
        Element element = new Element(Tag.valueOf("tag"), null);
        assertEquals(0, element.siblingElements().size());
    }

    @Test
    public void testSiblingElements_EmptyParent() {
        Element element = new Element(Tag.valueOf("tag"), null, new Attributes());
        Element parent = element.parent();
        assertEquals(0, parent.children().size());
        assertEquals(0, element.siblingElements().size());
    }

    @Test
    public void testSiblingElements_SingleChild() {
        Element element = new Element(Tag.valueOf("tag"), null, new Attributes());
        Element parent = element.parent();
        parent.appendChild(new Element(Tag.valueOf("tag"), null));
        assertEquals(1, element.siblingElements().size());
    }

    @Test
    public void testSiblingElements_MultipleChildren() {
        Element element = new Element(Tag.valueOf("tag"), null, new Attributes());
        Element parent = element.parent();
        parent.appendChild(new Element(Tag.valueOf("tag"), null));
        parent.appendChild(new Element(Tag.valueOf("tag"), null));
        assertEquals(2, element.siblingElements().size());
    }

    @Test
    public void testSiblingElements_ChildrenWithText() {
        Element element = new Element(Tag.valueOf("tag"), null, new Attributes());
        Element parent = element.parent();
        parent.appendChild(new Element(Tag.valueOf("tag"), null).text("text"));
        parent.appendChild(new Element(Tag.valueOf("tag"), null).text("text2"));
        assertEquals(2, element.siblingElements().size());
    }

    @Test
    public void testSiblingElements_ChildrenWithAttributes() {
        Element element = new Element(Tag.valueOf("tag"), null, new Attributes());
        Element parent = element.parent();
        parent.appendChild(new Element(Tag.valueOf("tag"), null).attr("attr", "value"));
        parent.appendChild(new Element(Tag.valueOf("tag"), null).attr("attr", "value2"));
        assertEquals(2, element.siblingElements().size());
    }

    @Test
    public void testSiblingElements_ChildrenWithMultipleAttributes() {
        Element element = new Element(Tag.valueOf("tag"), null, new Attributes());
        Element parent = element.parent();
        parent.appendChild(new Element(Tag.valueOf("tag"), null).attr("attr1", "value1").attr("attr2", "value2"));
        parent.appendChild(new Element(Tag.valueOf("tag"), null).attr("attr1", "value1").attr("attr2", "value2"));
        assertEquals(2, element.siblingElements().size());
    }

    @Test
    public void testSiblingElements_ChildrenWithNamespace() {
        Element element = new Element(Tag.valueOf("tag"), null, new Attributes());
        Element parent = element.parent();
        parent.appendChild(new Element(Tag.valueOf("tag"), null, "namespace", new Attributes()));
        parent.appendChild(new Element(Tag.valueOf("tag"), null, "namespace", new Attributes()));
        assertEquals(2, element.siblingElements().size());
    }

    @Test
    public void testSiblingElements_ChildrenWithComment() {
        Element element = new Element(Tag.valueOf("tag"), null, new Attributes());
        Element parent = element.parent();
        parent.appendChild(new Element(Tag.valueOf("tag"), null).comment("comment"));
        parent.appendChild(new Element(Tag.valueOf("tag"), null).comment("comment2"));
        assertEquals(2, element.siblingElements().size());
    }

    @Test
    public void testSiblingElements_ChildrenWithProcessingInstruction() {
        Element element = new Element(Tag.valueOf("tag"), null, new Attributes());
        Element parent = element.parent();
        parent.appendChild(new Element(Tag.valueOf("tag"), null).processingInstruction("instruction"));
        parent.appendChild(new Element(Tag.valueOf("tag"), null).processingInstruction("instruction2"));
        assertEquals(2, element.siblingElements().size());
    }

    @Test
    public void testSiblingElements_ChildrenWithUnknownTag() {
        Element element = new Element(Tag.valueOf("tag"), null, new Attributes());
        Element parent = element.parent();
        parent.appendChild(new Element(Tag.valueOf("unknown-tag"), null));
        parent.appendChild(new Element(Tag.valueOf("unknown-tag"), null));
        assertEquals(2, element.siblingElements().size());
    }
}
